// Mode: Run Once for Each Item
// Turns one raw Gmail message into a clean, predictable structure.
const cfg = $('Config').first().json.cfg;
const mail = $input.item.json;
const binary = $input.item.binary ?? {};

const sender = mail.from?.value?.[0] ?? {};
const fromEmail = String(sender.address ?? '').trim().toLowerCase();
const fromName = String(sender.name ?? '').trim();
const domain = fromEmail.includes('@') ? fromEmail.split('@')[1] : '';
const freemailDomains = String(cfg.freemailDomains ?? '')
  .split(',').map((d) => d.trim().toLowerCase()).filter(Boolean);

// Prefer the plain-text part; fall back to stripped HTML.
const htmlAsText = String(mail.html ?? '')
  .replace(/<(br|\/p|\/div|\/tr)\s*\/?>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/[ \t]+/g, ' ');
const bodyText = (String(mail.text ?? '').trim() || htmlAsText.trim()).slice(0, 12000);

// First PDF attachment (if any) is passed on for text extraction.
const pdfKey = Object.keys(binary).find((key) => {
  const file = binary[key] ?? {};
  return String(file.mimeType ?? '').toLowerCase() === 'application/pdf'
    || /\.pdf$/i.test(String(file.fileName ?? ''));
}) ?? null;

return {
  json: {
    messageId: mail.id,
    threadId: mail.threadId,
    receivedAt: mail.date ?? new Date().toISOString(),
    subject: String(mail.subject ?? '').trim(),
    fromEmail,
    fromName,
    domain,
    isFreemail: freemailDomains.includes(domain),
    bodyText,
    pdfKey,
    attachmentCount: Object.keys(binary).length,
  },
  binary,
};

// Mode: Run Once for Each Item
// Builds the Claude API request (Messages API + structured outputs). The AI only EXTRACTS data - it never calculates prices.
const cfg = $('Config').first().json.cfg;
const mail = $('Normalize Email').item.json;

// Separate what the sender NEWLY wrote from the quoted conversation below it
// (Gmail "Am ... schrieb", Outlook/Hotmail "Von:/From:" blocks, "> " lines).
// Without this, a reply like "passt, wir beauftragen Sie" would be read together with
// our quoted offer and could be mistaken for a new transport request.
const QUOTE_START = [
  /^\s*>/,
  /^\s*(am|on)\b.*(schrieb|wrote)/i,
  /(schrieb|wrote)\s*.*:\s*$/i,
  /^\s*-{2,}\s*(original|ursprüngliche|forwarded|weitergeleitete)/i,
  /^\s*_{5,}\s*$/,
];
// "Von:/From:" only counts as a mail header if it contains an address or is followed by
// "Gesendet:/Sent:/Datum:/Date:" - so "Von: 80331 München" in a request is NOT cut off.
const isHeaderBlock = (lines, i) => /^\s*(von|from)\s*:/i.test(lines[i])
  && (/@/.test(lines[i]) || lines.slice(i + 1, i + 4).some((l) => /^\s*(gesendet|sent|datum|date)\s*:/i.test(l)));
const bodyLines = String(mail.bodyText ?? '').split(/\r?\n/);
const cut = bodyLines.findIndex((line, i) => QUOTE_START.some((re) => re.test(line)) || isHeaderBlock(bodyLines, i));
const newText = (cut === -1 ? bodyLines : bodyLines.slice(0, cut)).join('\n').trim();
const quotedHistory = cut === -1 ? '' : bodyLines.slice(cut).join('\n').trim().slice(0, 4000);

// Input is either the PDF extraction result or (no PDF) the normalised email itself.
const pdfText = typeof $json.text === 'string' ? $json.text.trim().slice(0, 12000) : '';
const pdfError = $json.error ? String($json.error.message ?? $json.error) : null;

// Claude structured outputs limit union types ("string|null"), so the schema uses
// plain types: missing text = "" and missing numbers = 0. The validation step treats both as "missing".
const str = (description) => (description ? { type: 'string', description } : { type: 'string' });
const numb = (description) => (description ? { type: 'number', description } : { type: 'number' });
const place = {
  type: 'object',
  additionalProperties: false,
  properties: {
    country_code: str('ISO 3166-1 alpha-2, e.g. DE, AT, IT. Empty string if unknown'),
    postal_code: str('Empty string if unknown'),
    city: str('Empty string if unknown'),
  },
  required: ['country_code', 'postal_code', 'city'],
};

const schema = {
  type: 'object',
  additionalProperties: false,
  properties: {
    email_type: {
      type: 'string',
      enum: ['transport_inquiry', 'order_confirmation', 'other'],
      description: 'Based ONLY on the NEW MESSAGE part',
    },
    confirmation_quote: str('For order_confirmation: the confirming sentence, copied word for word. Otherwise empty string'),
    language: { type: 'string', enum: ['de', 'en', 'other'] },
    customer: {
      type: 'object',
      additionalProperties: false,
      properties: {
        first_name: str(), last_name: str(), company_name: str(), phone: str(),
      },
      required: ['first_name', 'last_name', 'company_name', 'phone'],
    },
    origin: place,
    destination: place,
    total_weight_kg: numb('Total gross weight in kg, only if stated, otherwise 0'),
    total_volume_m3: numb('Total volume in m3, only if stated, otherwise 0'),
    packages: {
      type: 'array',
      description: 'One entry per package type, exactly as stated in the email',
      items: {
        type: 'object',
        additionalProperties: false,
        properties: {
          count: { type: 'integer' },
          type: str('e.g. EUR pallet, one-way pallet, box, crate'),
          length_cm: numb(), width_cm: numb(), height_cm: numb(), weight_kg_each: numb(),
        },
        required: ['count', 'type', 'length_cm', 'width_cm', 'height_cm', 'weight_kg_each'],
      },
    },
    cargo_description: str(),
    dangerous_goods: { type: 'boolean', description: 'true only if ADR / hazardous goods are mentioned' },
    pickup_date: str('YYYY-MM-DD or as written (e.g. KW 42)'),
    delivery_deadline: str(),
    special_requirements: str('e.g. tail lift, appointment, temperature'),
  },
  required: [
    'email_type', 'confirmation_quote', 'language', 'customer', 'origin', 'destination',
    'total_weight_kg', 'total_volume_m3', 'packages', 'cargo_description',
    'dangerous_goods', 'pickup_date', 'delivery_deadline', 'special_requirements',
  ],
};

const systemPrompt = [
  'You extract transport request data for a German freight forwarder.',
  'Rules:',
  '- Extract ONLY information that is explicitly written in the email or attachment. Never guess or invent values.',
  '- If a value is missing, use an empty string for text and 0 for numbers.',
  '- Convert units only: tonnes to kg (1,2 t = 1200), metres to cm. Decimal commas are decimals (1,5 = 1.5).',
  '- Do NOT calculate totals, volumes or prices. List packages exactly as described.',
  '- Countries as ISO-2 codes (Deutschland = DE, Österreich = AT, Italien = IT).',
  '- Classify email_type using ONLY the NEW MESSAGE. The QUOTED HISTORY is earlier conversation (often our own offer) and is context only.',
  '- transport_inquiry: the sender asks for a price/offer for a transport.',
  "- order_confirmation: the sender accepts our offer or places the order (e.g. 'wir beauftragen Sie', 'Auftrag erteilt', 'passt, bitte durchführen', 'we accept your offer').",
  '- Questions, price negotiations, rejections, invoices, newsletters, spam and notifications are other.',
  "- Examples: 'passt, wir beauftragen Sie hiermit' = order_confirmation. 'Ja, bitte so durchführen' = order_confirmation. 'Geht es auch für 190 Euro?' = other. 'Können Sie 2 Paletten von Köln nach Paris anbieten?' = transport_inquiry.",
  '- For order_confirmation and other: fill transport fields only if they are newly written in the NEW MESSAGE, otherwise leave them empty / 0.',
].join('\n');

const userPrompt = [
  `SUBJECT: ${mail.subject}`,
  `FROM: ${mail.fromName} <${mail.fromEmail}>`,
  '',
  'NEW MESSAGE (written by the sender):',
  newText || '(empty)',
  '',
  'QUOTED HISTORY (context only, do not extract from it):',
  quotedHistory || '(none)',
  '',
  'ATTACHMENT TEXT:',
  pdfText || '(no attachment)',
].join('\n');

const llmRequest = {
  model: cfg.anthropicModel,
  max_tokens: 2048,
  temperature: 0,
  system: systemPrompt,
  messages: [{ role: 'user', content: userPrompt }],
  output_config: { format: { type: 'json_schema', schema } },
};

return { json: { ...mail, newText, hasQuotedHistory: quotedHistory.length > 0, pdfTextLength: pdfText.length, pdfError, llmRequest } };

// Mode: Run Once for Each Item
// Parses the AI answer and validates it with plain code (not with AI).
const cfg = $('Config').first().json.cfg;
const { llmRequest, ...ctx } = $('Build AI Request').item.json;

// Claude Messages API response: the JSON is in the first text block.
if ($json.stop_reason === 'refusal') throw new Error('AI refused the request');
if ($json.stop_reason === 'max_tokens') throw new Error('AI answer was cut off (max_tokens) - increase max_tokens');
const textBlock = ($json.content ?? []).find((block) => block.type === 'text');
if (!textBlock) throw new Error(`AI response has no text: ${JSON.stringify($json).slice(0, 300)}`);

let ai;
try {
  ai = JSON.parse(textBlock.text);
} catch (error) {
  throw new Error(`AI returned invalid JSON: ${String(textBlock.text).slice(0, 300)}`);
}

// ---------- helpers ----------
const num = (value) => {
  if (value === null || value === undefined || value === '') return null;
  const n = typeof value === 'number' ? value : Number(String(value).replace(/\s/g, '').replace(',', '.'));
  return Number.isFinite(n) && n > 0 ? n : null;
};
const clean = (value) => {
  const s = value === null || value === undefined ? '' : String(value).trim();
  return s.length ? s : null;
};
const round = (n, d = 2) => (n === null ? null : Math.round(n * 10 ** d) / 10 ** d);
const normPlace = (p = {}) => ({
  countryCode: clean(p.country_code)?.toUpperCase().slice(0, 2) ?? null,
  postalCode: clean(p.postal_code)?.replace(/\s+/g, '').toUpperCase() ?? null,
  city: clean(p.city),
});

const origin = normPlace(ai.origin);
const destination = normPlace(ai.destination);

// ---------- quantities (calculated here, not by the AI) ----------
const packages = (ai.packages ?? [])
  .map((p) => ({
    count: Number.isInteger(Number(p.count)) && Number(p.count) > 0 ? Number(p.count) : null,
    type: clean(p.type),
    lengthCm: num(p.length_cm),
    widthCm: num(p.width_cm),
    heightCm: num(p.height_cm),
    weightKgEach: num(p.weight_kg_each),
  }))
  .filter((p) => p.count !== null);

const allHaveDims = packages.length > 0 && packages.every((p) => p.lengthCm && p.widthCm && p.heightCm);
const allHaveWeight = packages.length > 0 && packages.every((p) => p.weightKgEach);
const palletCount = packages
  .filter((p) => /pal/i.test(p.type ?? ''))
  .reduce((sum, p) => sum + p.count, 0) || null;

let weightKg = num(ai.total_weight_kg);
let weightSource = weightKg ? 'stated' : null;
if (!weightKg && allHaveWeight) {
  weightKg = packages.reduce((sum, p) => sum + p.count * p.weightKgEach, 0);
  weightSource = 'calculated_from_packages';
}

let volumeM3 = num(ai.total_volume_m3);
let volumeSource = volumeM3 ? 'stated' : null;
if (!volumeM3 && allHaveDims) {
  volumeM3 = packages.reduce((sum, p) => sum + (p.count * p.lengthCm * p.widthCm * p.heightCm) / 1e6, 0);
  volumeSource = 'calculated_from_dimensions';
}
if (!volumeM3 && palletCount) {
  volumeM3 = palletCount * Number(cfg.palletVolumeM3);
  volumeSource = 'estimated_from_pallets';
}

// ---------- completeness check ----------
const LABELS = {
  origin: { de: 'Postleitzahl und Ort der Abholung', en: 'pickup postcode and city' },
  destination: { de: 'Postleitzahl und Ort der Zustellung', en: 'delivery postcode and city' },
  weight: { de: 'Gesamtgewicht in kg', en: 'total weight in kg' },
  volume: { de: 'Maße (L x B x H in cm) oder Anzahl der Paletten', en: 'dimensions (L x W x H in cm) or number of pallets' },
};
const missing = [];
if (!origin.countryCode || !origin.postalCode) missing.push('origin');
if (!destination.countryCode || !destination.postalCode) missing.push('destination');
if (!weightKg) missing.push('weight');
if (!volumeM3) missing.push('volume');

const language = String(ai.language ?? '').toLowerCase() === 'en' ? 'en' : 'de';
// Claude may vary the casing of enum values, so compare in lower case.
const emailType = String(ai.email_type ?? '').toLowerCase();
let status = 'complete';
if (emailType === 'order_confirmation') status = 'order_confirmation';
else if (emailType !== 'transport_inquiry') status = 'not_rfq';
else if (missing.length) status = 'incomplete';

const nameParts = ctx.fromName.split(/\s+/).filter(Boolean);

return {
  json: {
    ...ctx,
    status,
    emailType,
    confirmationQuote: clean(ai.confirmation_quote),
    language,
    customer: {
      firstName: clean(ai.customer?.first_name) ?? nameParts[0] ?? null,
      lastName: clean(ai.customer?.last_name) ?? (nameParts.length > 1 ? nameParts.slice(1).join(' ') : null),
      companyName: clean(ai.customer?.company_name),
      phone: clean(ai.customer?.phone),
    },
    origin,
    destination,
    packages,
    palletCount,
    weightKg: round(weightKg, 1),
    weightSource,
    volumeM3: round(volumeM3, 2),
    volumeSource,
    cargoDescription: clean(ai.cargo_description),
    dangerousGoods: ai.dangerous_goods === true,
    pickupDate: clean(ai.pickup_date),
    deliveryDeadline: clean(ai.delivery_deadline),
    specialRequirements: clean(ai.special_requirements),
    missing,
    missingLabels: missing.map((key) => LABELS[key][language]),
    ai: { model: $json.model ?? cfg.anthropicModel, inputTokens: $json.usage?.input_tokens ?? null, outputTokens: $json.usage?.output_tokens ?? null },
  },
};

// Mode: Run Once for All Items
// Packs all price list rows into ONE item, so every request gets the full list.
const rates = $input.all()
  .map((item) => item.json)
  .filter((row) => row && Object.keys(row).length > 0 && row.carrier);
return [{ json: { rates } }];

// Mode: Run Once for Each Item
// Deterministic freight cost calculation from the price list (no AI involved).
const cfg = $('Config').first().json.cfg;
const { rates = [], ...r } = $json;

const num = (value) => {
  if (value === null || value === undefined || value === '') return null;
  const n = typeof value === 'number' ? value : Number(String(value).replace(/\s|€/g, '').replace(',', '.'));
  return Number.isFinite(n) ? n : null;
};
const round2 = (n) => Math.round(n * 100) / 100;
// First two digits of the postcode. Pads, because Google Sheets turns "01" into 1.
const zip2 = (value) => {
  const digits = String(value ?? '').replace(/\D/g, '');
  return digits.length >= 2 ? digits.slice(0, 2) : digits.padStart(2, '0');
};
const cc = (value) => String(value ?? '').trim().toUpperCase();
const today = new Date().toISOString().slice(0, 10);
const isValid = (row) => {
  const until = String(row.valid_until ?? '').trim();
  if (!until) return true;
  const iso = /^\d{2}\.\d{2}\.\d{4}$/.test(until) ? until.split('.').reverse().join('-') : until;
  return iso >= today;
};

const lane = {
  originCc: cc(r.origin.countryCode),
  originZip2: zip2(r.origin.postalCode),
  destCc: cc(r.destination.countryCode),
  destZip2: zip2(r.destination.postalCode),
};

const volumeFactor = Number(cfg.volumeFactorKgPerM3);
const volumeWeightKg = Math.round(r.volumeM3 * volumeFactor);
const chargeableKg = Math.max(Math.round(r.weightKg), volumeWeightKg);

const offers = rates
  .filter((row) => cc(row.origin_cc) === lane.originCc
    && zip2(row.origin_zip2) === lane.originZip2
    && cc(row.dest_cc) === lane.destCc
    && zip2(row.dest_zip2) === lane.destZip2
    && isValid(row))
  .map((row) => {
    const ratePer100 = num(row.rate_per_100kg);
    const minCharge = num(row.min_charge) ?? 0;
    const fuelPct = num(row.fuel_pct) ?? 0;
    if (ratePer100 === null) return null;
    const base = Math.max(minCharge, (chargeableKg / 100) * ratePer100);
    const cost = round2(base * (1 + fuelPct / 100));
    return {
      carrier: String(row.carrier),
      ratePer100kg: ratePer100,
      minCharge,
      fuelPct,
      transitDays: num(row.transit_days),
      baseCost: round2(base),
      cost,
    };
  })
  .filter(Boolean)
  .sort((a, b) => a.cost - b.cost);

const best = offers[0] ?? null;
const route = `${r.origin.postalCode} ${r.origin.city ?? ''} (${lane.originCc}) → ${r.destination.postalCode} ${r.destination.city ?? ''} (${lane.destCc})`.replace(/\s+/g, ' ');

const slackManualText = [
  ':red_circle: *Keine Rate gefunden* – bitte manuell kalkulieren',
  `*Kunde:* ${r.customer.companyName ?? r.fromName ?? r.fromEmail} <${r.fromEmail}>`,
  `*Strecke:* ${route}`,
  `*Sendung:* ${r.weightKg} kg, ${r.volumeM3} m³ → frachtpfl. ${chargeableKg} kg`,
  `*Lane-Schlüssel:* ${lane.originCc}-${lane.originZip2} → ${lane.destCc}-${lane.destZip2}`,
].join('\n');

return {
  json: {
    ...r,
    lane,
    route,
    volumeFactorKgPerM3: volumeFactor,
    volumeWeightKg,
    chargeableKg,
    rateFound: best !== null,
    bestOffer: best,
    alternativeOffers: offers.slice(1, 4),
    ratesChecked: rates.length,
    slackManualText,
  },
};

// Mode: Run Once for Each Item
// Decides "new or existing customer" from the Twenty search result.
const r = $('Calculate Freight Cost').item.json;
const response = $json;

const list = Array.isArray(response.data)
  ? response.data
  : Object.values(response.data ?? {}).find(Array.isArray) ?? [];
const hostOf = (url) => String(url ?? '').toLowerCase()
  .replace(/^https?:\/\//, '').replace(/^www\./, '').split(/[/?#]/)[0];
const num = (v) => (v === null || v === undefined || v === '' || !Number.isFinite(Number(v)) ? null : Number(v));

let match = null;
if (r.isFreemail) {
  match = list.find((p) => String(p.emails?.primaryEmail ?? '').toLowerCase() === r.fromEmail) ?? null;
} else {
  match = list.find((c) => hostOf(c.domainName?.primaryLinkUrl) === r.domain) ?? null;
}

const customerStatus = match ? 'EXISTING' : 'NEW';
const companyName = r.customer.companyName
  ?? (r.isFreemail ? `Privatkunde ${[r.customer.firstName, r.customer.lastName].filter(Boolean).join(' ') || r.fromEmail}` : r.domain);

const twentyCompanyPayload = { name: companyName };
if (!r.isFreemail) twentyCompanyPayload.domainName = { primaryLinkUrl: `https://${r.domain}` };

const twentyPersonPayload = {
  name: { firstName: r.customer.firstName ?? '', lastName: r.customer.lastName ?? '' },
  emails: { primaryEmail: r.fromEmail },
};

return {
  json: {
    ...r,
    customerStatus,
    companyId: r.isFreemail ? (match?.companyId ?? null) : (match?.id ?? null),
    personId: r.isFreemail ? (match?.id ?? null) : null,
    companyName: r.isFreemail ? companyName : (match?.name ?? companyName),
    marginPct: r.isFreemail ? null : num(match?.marginPct),
    twentyCompanyPayload,
    twentyPersonPayload,
  },
};

// Mode: Run Once for Each Item
// Collects the IDs of the newly created company and person.
// Both CRM calls continue on error (e.g. "duplicate entry" when a record is still in
// Twenty's trash). The offer is still prepared and the team is warned instead of the run failing.
const base = $('Resolve Customer').item.json;
const idOf = (response) => {
  if (!response || response.error) return null;
  if (response.id) return response.id;
  const inner = response.data && typeof response.data === 'object' ? Object.values(response.data)[0] : null;
  return inner?.id ?? null;
};
const reason = (response) => {
  const text = JSON.stringify(response?.error ?? response ?? {});
  return /duplicate|unique/i.test(text) ? 'existiert bereits – evtl. im CRM-Papierkorb' : 'konnte nicht angelegt werden';
};

const companyResponse = $('Twenty: Create Company').item.json;
const companyId = idOf(companyResponse);
const personId = idOf($json);

const crmWarnings = [];
if (!companyId) crmWarnings.push(`:warning: CRM: Firma „${base.companyName}" ${reason(companyResponse)} – bitte im CRM prüfen`);
if (!personId) crmWarnings.push(`:warning: CRM: Kontakt ${base.fromEmail} ${reason($json)} – bitte im CRM prüfen`);

return { json: { ...base, customerStatus: 'NEW', companyId, personId, crmWarnings } };

// Mode: Run Once for Each Item
// Adds the margin, writes the offer email and prepares the CRM record.
const cfg = $('Config').first().json.cfg;
const r = $json;
const best = r.bestOffer;

const marginPct = r.marginPct ?? Number(cfg.defaultMarginPct);
const priceEur = Math.round(best.cost * (1 + marginPct / 100) * 100) / 100;
const marginEur = Math.round((priceEur - best.cost) * 100) / 100;

const validUntil = new Date(Date.now() + Number(cfg.offerValidityDays) * 86400000);
const locale = r.language === 'en' ? 'en-GB' : 'de-DE';
const eur = (n) => new Intl.NumberFormat(locale, { style: 'currency', currency: 'EUR' }).format(n);
const dec = (n, d = 2) => new Intl.NumberFormat(locale, { maximumFractionDigits: d }).format(n);
const date = (d) => new Intl.DateTimeFormat(locale, { day: '2-digit', month: '2-digit', year: 'numeric', timeZone: 'Europe/Berlin' }).format(d);

const place = (p) => `${p.postalCode} ${p.city ?? ''} (${p.countryCode})`.replace(/\s+/g, ' ');
const name = [r.customer.firstName, r.customer.lastName].filter(Boolean).join(' ');
const goods = r.language === 'en'
  ? `${r.palletCount ? `${r.palletCount} pallet(s), ` : ''}${dec(r.weightKg, 1)} kg, ${dec(r.volumeM3)} m³`
  : `${r.palletCount ? `${r.palletCount} Palette(n), ` : ''}${dec(r.weightKg, 1)} kg, ${dec(r.volumeM3)} m³`;

const de = [
  name ? `Guten Tag ${name},` : 'Sehr geehrte Damen und Herren,',
  '',
  'vielen Dank für Ihre Transportanfrage. Gerne bieten wir Ihnen folgenden Transport an:',
  '',
  `Abholung:              ${place(r.origin)}`,
  `Zustellung:            ${place(r.destination)}`,
  `Sendung:               ${goods}`,
  `Frachtpflichtiges Gew.: ${dec(r.chargeableKg, 0)} kg`,
  r.pickupDate ? `Abholtermin:           ${r.pickupDate}` : null,
  best.transitDays ? `Laufzeit:              ca. ${best.transitDays} Werktag(e)` : null,
  `Preis:                 ${eur(priceEur)} zzgl. gesetzl. MwSt., inkl. Dieselzuschlag`,
  '',
  r.dangerousGoods ? 'Hinweis: Da es sich um Gefahrgut handelt, benötigen wir vorab UN-Nummer und Sicherheitsdatenblatt.' : null,
  r.volumeSource === 'estimated_from_pallets' ? 'Hinweis: Das Volumen wurde auf Basis von Standard-Europaletten angenommen. Bitte bestätigen Sie die Maße.' : null,
  `Dieses Angebot ist gültig bis zum ${date(validUntil)}. ${cfg.termsLineDe}`,
  '',
  'Wir freuen uns auf Ihren Auftrag.',
  '',
  'Mit freundlichen Grüßen',
  cfg.senderName,
  cfg.companyName,
];

const en = [
  name ? `Dear ${name},` : 'Dear Sir or Madam,',
  '',
  'thank you for your transport request. We are pleased to offer the following transport:',
  '',
  `Pickup:            ${place(r.origin)}`,
  `Delivery:          ${place(r.destination)}`,
  `Shipment:          ${goods}`,
  `Chargeable weight: ${dec(r.chargeableKg, 0)} kg`,
  r.pickupDate ? `Pickup date:       ${r.pickupDate}` : null,
  best.transitDays ? `Transit time:      approx. ${best.transitDays} working day(s)` : null,
  `Price:             ${eur(priceEur)} plus VAT, incl. fuel surcharge`,
  '',
  r.dangerousGoods ? 'Note: as these are dangerous goods, we need the UN number and safety data sheet in advance.' : null,
  r.volumeSource === 'estimated_from_pallets' ? 'Note: the volume was estimated based on standard euro pallets. Please confirm the dimensions.' : null,
  `This offer is valid until ${date(validUntil)}. ${cfg.termsLineEn}`,
  '',
  'We look forward to your order.',
  '',
  'Kind regards',
  cfg.senderName,
  cfg.companyName,
];

const twentyOpportunityPayload = {
  name: `${r.companyName} | ${r.origin.postalCode} → ${r.destination.postalCode}`,
  amount: { amountMicros: Math.round(priceEur * 1e6), currencyCode: 'EUR' },
  stage: cfg.twentyStageNew,
};
if (r.companyId) twentyOpportunityPayload.companyId = r.companyId;
if (r.personId) twentyOpportunityPayload.pointOfContactId = r.personId;
if (cfg.twentyUseCustomFields) {
  twentyOpportunityPayload.route = r.route;
  twentyOpportunityPayload.chargeableKg = r.chargeableKg;
}
// The Gmail thread links a later customer reply ("wir beauftragen Sie") to this opportunity.
if (cfg.twentyThreadField) twentyOpportunityPayload[cfg.twentyThreadField] = r.threadId;

const warnings = [
  ...(r.crmWarnings ?? []),
  r.dangerousGoods ? ':biohazard_sign: Gefahrgut (ADR) – bitte prüfen' : null,
  r.volumeSource === 'estimated_from_pallets' ? ':straight_ruler: Volumen aus Palettenanzahl geschätzt' : null,
  r.pdfError ? `:page_facing_up: PDF konnte nicht gelesen werden (${r.pdfError})` : null,
].filter(Boolean);

return {
  json: {
    ...r,
    marginPct,
    marginEur,
    priceEur,
    validUntil: validUntil.toISOString().slice(0, 10),
    replySubject: /^(re|aw):/i.test(r.subject) ? r.subject : `Re: ${r.subject}`,
    replyBody: (r.language === 'en' ? en : de).filter((line) => line !== null).join('\n'),
    twentyOpportunityPayload,
    warnings,
  },
};

// Mode: Run Once for Each Item
// Adds the CRM record ID and prepares the team notification.
const cfg = $('Config').first().json.cfg;
const q = $('Build Quote').item.json;
const idOf = (response) => {
  if (!response) return null;
  if (response.id) return response.id;
  const inner = response.data && typeof response.data === 'object' ? Object.values(response.data)[0] : null;
  return inner?.id ?? null;
};
const opportunityId = idOf($json);
const eur = (n) => new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR' }).format(n);
const crmLink = opportunityId ? `${cfg.twentyPublicUrl}/object/opportunity/${opportunityId}` : null;

const slackText = [
  `:package: *Neues Angebot bereit* (${q.customerStatus === 'NEW' ? 'Neukunde' : 'Bestandskunde'})`,
  `*Kunde:* ${q.companyName} <${q.fromEmail}>`,
  `*Strecke:* ${q.route}`,
  `*Sendung:* ${q.weightKg} kg / ${q.volumeM3} m³ → frachtpfl. ${q.chargeableKg} kg`,
  `*EK:* ${eur(q.bestOffer.cost)} (${q.bestOffer.carrier})  |  *VK:* ${eur(q.priceEur)}  |  *Marge:* ${q.marginPct}% (${eur(q.marginEur)})`,
  ...q.warnings,
  ':email: Entwurf liegt im Postfach – bitte prüfen und senden.',
  crmLink ? `:link: CRM: ${crmLink}` : null,
].filter(Boolean).join('\n');

return { json: { ...q, opportunityId, crmLink, slackText } };

// Mode: Run Once for Each Item
// Prepares a polite "please send the missing data" draft plus a team message.
const cfg = $('Config').first().json.cfg;
const r = $json;
const name = [r.customer.firstName, r.customer.lastName].filter(Boolean).join(' ');
const list = r.missingLabels.map((label) => `- ${label}`).join('\n');

const text = r.language === 'en'
  ? [
      name ? `Dear ${name},` : 'Dear Sir or Madam,',
      '',
      'thank you for your transport request. To give you an accurate price, we still need the following information:',
      '',
      list,
      '',
      'As soon as we have these details, you will receive our offer promptly.',
      '',
      'Kind regards',
      cfg.senderName,
      cfg.companyName,
    ]
  : [
      name ? `Guten Tag ${name},` : 'Sehr geehrte Damen und Herren,',
      '',
      'vielen Dank für Ihre Transportanfrage. Für ein genaues Angebot benötigen wir noch folgende Angaben:',
      '',
      list,
      '',
      'Sobald uns diese Informationen vorliegen, erhalten Sie umgehend unser Angebot.',
      '',
      'Mit freundlichen Grüßen',
      cfg.senderName,
      cfg.companyName,
    ];

const slackText = [
  ':warning: *Anfrage unvollständig* – Rückfrage-Entwurf liegt im Postfach',
  `*Von:* ${r.fromName || '-'} <${r.fromEmail}>`,
  `*Betreff:* ${r.subject || '-'}`,
  `*Es fehlt:* ${r.missingLabels.join(', ')}`,
].join('\n');

return {
  json: {
    ...r,
    replySubject: /^(re|aw):/i.test(r.subject) ? r.subject : `Re: ${r.subject}`,
    replyBody: text.join('\n'),
    slackText,
  },
};

// Mode: Run Once for Each Item
// Team message for customer replies. The AI only SUGGESTS; an employee sets the
// opportunity to "won" in the CRM (human in the loop).
const cfg = $('Config').first().json.cfg;
const r = $json;
const opp = r.threadOpportunity;

const eur = (micros) => (micros ? new Intl.NumberFormat('de-DE', { style: 'currency', currency: 'EUR' }).format(micros / 1e6) : '-');
const sender = `${r.fromName || r.fromEmail} <${r.fromEmail}>`;
const excerpt = String(r.newText ?? '').replace(/\s+/g, ' ').trim().slice(0, 300);
const said = r.confirmationQuote || excerpt;
const crm = opp ? `:link: CRM: ${cfg.twentyPublicUrl}/object/opportunity/${opp.id}` : null;

let outcome;
let lines;
if (!opp) {
  outcome = 'no_match';
  lines = [
    ':handshake: *Auftragsbestätigung erkannt* – keine passende Verkaufschance gefunden',
    `*Von:* ${sender}`,
    `*Betreff:* ${r.subject || '-'}`,
    said ? `_„${said}“_` : null,
    ':point_right: Bitte die Verkaufschance im CRM manuell zuordnen und auf *gewonnen* setzen.',
  ];
} else if (r.isConfirmation && opp.stage === cfg.twentyStageWon) {
  outcome = 'already_won';
  lines = [':information_source: *Auftragsbestätigung erkannt* – Verkaufschance ist bereits gewonnen', `*Auftrag:* ${opp.name}`, crm];
} else if (r.isConfirmation) {
  outcome = 'suggest_won';
  lines = [
    ':handshake: *Kunde hat bestätigt* – Vorschlag: Verkaufschance auf *gewonnen* setzen',
    `*Auftrag:* ${opp.name}  |  *Angebot:* ${eur(opp.amount?.amountMicros)}`,
    `*Von:* ${sender}`,
    said ? `_„${said}“_` : null,
    `:point_right: Bitte prüfen und im CRM auf *${cfg.twentyStageWon}* ziehen – danach geht der Auftrag automatisch ans TMS.`,
    crm,
  ];
} else {
  outcome = 'reply_needs_review';
  lines = [
    ':speech_balloon: *Kunde hat auf ein Angebot geantwortet* – keine eindeutige Bestätigung, bitte lesen',
    `*Auftrag:* ${opp.name}  |  *Angebot:* ${eur(opp.amount?.amountMicros)}`,
    `*Von:* ${sender}`,
    excerpt ? `_„${excerpt}“_` : null,
    crm,
  ];
}

return { json: { messageId: r.messageId, outcome, confirmationSignal: r.confirmationSignal, slackText: lines.filter(Boolean).join('\n') } };

// Mode: Run Once for Each Item
// Deterministic routing BEFORE trusting the AI classification:
// a reply inside a Gmail thread where we already sent an offer is never ignored.
// AI + keywords only decide whether that reply is a confirmation (the employee decides anyway).
const r = $('Parse & Validate').item.json;
const res = $json;

const list = res.error ? [] : (Array.isArray(res.data)
  ? res.data
  : Object.values(res.data ?? {}).find(Array.isArray) ?? []);
const threadOpportunity = [...list]
  .sort((a, b) => String(b.createdAt ?? '').localeCompare(String(a.createdAt ?? '')))[0] ?? null;

// Backup signal for clear confirmations, in case the AI answers "other".
const text = String(r.newText ?? '');
const CONFIRM = /(beauftrag|auftrag\s+(ist\s+)?erteilt|angebot\s+(wird\s+)?angenommen|nehmen\s+(das|ihr)\s+angebot\s+an|wir\s+bestätigen|hiermit\s+bestätig|bitte\s+(durchführen|ausführen|buchen)|we\s+accept|accept(ed)?\s+your\s+(offer|quote)|please\s+proceed|go\s+ahead)/i;
const NEGATION = /\b(nicht|kein|keine|keinen|leider|zu\s+teuer|absage|abgesagt|storn\w*|cancel\w*|declin\w*|reject\w*|not)\b/i;
const keywordConfirm = CONFIRM.test(text) && !NEGATION.test(text);
const aiConfirm = r.emailType === 'order_confirmation';
const isConfirmation = aiConfirm || keywordConfirm;

let status = r.status;
if (threadOpportunity) status = 'offer_reply';            // known offer thread -> always to the team
else if (isConfirmation) status = 'order_confirmation';   // confirmation, but thread unknown

return {
  json: {
    ...r,
    status,
    threadOpportunity,
    isConfirmation,
    confirmationSignal: aiConfirm && keywordConfirm ? 'ai+keywords' : aiConfirm ? 'ai' : keywordConfirm ? 'keywords' : 'none',
    threadLookupFailed: Boolean(res.error),
  },
};
